49	@Slf4j
50	public class SparkSizeBasedClusteringPlanStrategy<T>
51	    extends PartitionAwareClusteringPlanStrategy<T, JavaRDD<HoodieRecord<T>>, JavaRDD<HoodieKey>, JavaRDD<WriteStatus>> {
