56	    super(table, engineContext, writeConfig);
57	  }
58	
59	  @Override
60	  protected Pair<Stream<HoodieClusteringGroup>, Boolean> buildClusteringGroupsForPartition(String partitionPath, List<FileSlice> fileSlices) {
61	    return super.buildClusteringGroupsForPartition(partitionPath, fileSlices);
62	  }
63	
64	  @Override
65	  protected Map<String, String> getStrategyParams() {
66	    Map<String, String> params = new HashMap<>();
67	    if (!StringUtils.isNullOrEmpty(getWriteConfig().getClusteringSortColumns())) {
68	      params.put(PLAN_STRATEGY_SORT_COLUMNS.key(), getWriteConfig().getClusteringSortColumns());
69	    }
70	    return params;
71	  }
72	
73	  @Override
74	  protected Stream<FileSlice> getFileSlicesEligibleForClustering(final String partition) {
75	    return super.getFileSlicesEligibleForClustering(partition)
76	        // Only files that have base file size smaller than small file size are eligible.
77	        .filter(slice -> slice.getBaseFile().map(HoodieBaseFile::getFileSize).orElse(0L) < getWriteConfig().getClusteringSmallFileLimit());
78	  }
