/**
 * A commit-aware clustering plan strategy that iterates through the table's commit history and builds a
 * clustering plan by grouping files from each commit by partition while respecting per-group size limits.
 *
 * <p>The strategy only considers commits with a requested time strictly after the configured earliest commit
 * to cluster. It tracks progress via a checkpoint key ({@link #CLUSTERING_COMMIT_CHECKPOINT_KEY}) stored in the
 * plan's extra metadata, allowing clustering to be run incrementally against the commit timeline.
 */
public class CommitBasedClusteringPlanStrategy<T, I, K, O> extends PartitionAwareClusteringPlanStrategy<T, I, K, O> {

  private static final Logger LOG = LoggerFactory.getLogger(CommitBasedClusteringPlanStrategy.class);

  /**
   * Key used in the extra metadata map to store the requested time of the last commit processed while
   * building the clustering plan.
   */
  public static final String CLUSTERING_COMMIT_CHECKPOINT_KEY = "clustering.commit.checkpoint";

  // The requested time of the last commit instant processed during plan generation, null if none processed.
